(x, y, t) => {
  const cx = 240, cy = 120;
  const phase = t * 0.2;
  const wx = Math.sin(x*0.018+t*0.4)*20 + Math.cos(y*0.012-t*0.3)*15 + Math.sin((x+y)*0.008+t*0.15)*10;
  const wy = Math.cos(y*0.018-t*0.35)*20 + Math.sin(x*0.014+t*0.45)*15 + Math.cos((x-y)*0.009-t*0.2)*10;
  const sx = x + wx, sy = y + wy;
  const wells = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.08, 2.2, 1.8],
    [320+Math.cos(t*0.45)*110, 160+Math.sin(t*0.6)*55, 0.1, 1.8, 1.5],
    [240+Math.sin(t*0.25+2)*150, 120+Math.cos(t*0.4+1)*100, 0.055, 2.5, 2.2],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.5+3)*70, 0.13, 1.4, 1.2],
    [380+Math.sin(t*0.35+4)*100, 50+Math.cos(t*0.8+2)*80, 0.065, 2.8, 2.5],
    [240+Math.cos(t*0.3+5)*130, 210+Math.sin(t*0.5)*90, 0.085, 2.0, 1.7],
    [60+Math.sin(t*0.55+3)*70, 40+Math.cos(t*0.65+4)*50, 0.11, 1.6, 2.0],
    [420+Math.cos(t*0.4+1)*80, 200+Math.sin(t*0.75+2)*60, 0.075, 2.3, 1.9]
  ];
  let aS = 0, iS = 0, gPE = 0, gKE = 0;
  for (const [sX, sY, f, sp, mass] of wells) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2) + 0.1;
    const grav = mass / (d * 0.5 + 1);
    const wave = Math.sin(d*f - t*sp);
    aS += wave * (1 + grav * 0.5);
    iS += Math.sin(d*f*0.6 + t*sp*0.5 + 1.8) * (1 + grav * 0.3);
    const potential = grav * Math.cos(d*f*0.3 - t*sp*0.2);
    const kinetic = grav * Math.abs(Math.sin(d*f*0.3 - t*sp*0.2));
    gPE += potential;
    gKE += kinetic;
  }
  const totalE = Math.sqrt(gPE*gPE + gKE*gKE);
  const act = aS/8, inh = iS/8;
  const bg = (Math.sin(sx*0.035+sy*0.028+t*0.9) + Math.sin(sx*0.028-sy*0.038+t*1.3))/2;
  const bg2 = Math.sin((sx+sy)*0.14+t*2.8)*0.25 + Math.sin((sx-sy)*0.11-t*2.2)*0.25;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cx, sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*4-t*1.8) + Math.sin(dist*0.035+ang*5-t*1.4))*0.35;
  const energyBoost = totalE * 0.15;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + bg2 + spiral + energyBoost)*2.5);
  const voro = Math.min(
    Math.sin(sx*0.13+0.5)*Math.sin(sy*0.13+0.5),
    Math.sin(sx*0.13-0.3)*Math.sin(sy*0.13-0.3)
  );
  const cell = Math.tanh((voro + Math.sin((sx+sy)*0.09+t*1.2)*0.4)*2.0)*0.35;
  const flow = Math.sin(ang*2 + dist*0.02 - t*1.5)*0.15;
  const blend = reaction*0.7 + cell*0.2 + flow*0.1;
  const v = Math.max(0, Math.min(1, blend*0.5+0.5));
  const neon = [
    [2,4,25],[5,10,60],[10,40,120],[0,180,255],[0,255,200],
    [100,255,50],[255,255,0],[255,140,0],[255,40,80],[255,0,180],
    [140,0,255],[60,0,180],[15,5,80],[2,4,25]
  ];
  const idx = v*(neon.length-1), i = Math.min(idx|0, neon.length-2), f = idx-i;
  const intensity = Math.abs(reaction);
  const glow = intensity > 0.5 ? 1.0 + (intensity-0.5)*1.2 : 1.0;
  const neonPop = intensity > 0.7 ? 1.4 : 1.0;
  const lum = glow * neonPop;
  const edgeBoost = Math.abs(reaction) > 0.8 ? 1.3 : 1.0;
  const finalLum = lum * edgeBoost;
  return [
    Math.min(255, (neon[i][0]+(neon[i+1][0]-neon[i][0])*f)*finalLum)|0,
    Math.min(255, (neon[i][1]+(neon[i+1][1]-neon[i][1])*f)*finalLum)|0,
    Math.min(255, (neon[i][2]+(neon[i+1][2]-neon[i][2])*f)*finalLum)|0
  ];
}
